scripts.continued_fraction:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # Initialize p_prev and p (corresponding to p_{-1} and p_0)
    p_prev = 1  # p_{-1}
    p = terms[0]  # p_0 = a_0

    # Apply the recurrence for each remaining term
    for i in range(1, len(terms)):
        a = terms[i]
        p_new = a * p + p_prev
        p_prev = p
        p = p_new

    return float(p)

scripts.floor_division_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute the sum of floor(A_i / B_i)
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count inversions: pairs (i, j) where i < j but values[i] > values[j]
    count = 0
    n = len(values)
    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1

    return float(count)

